public void initValue()
{
    FormDataSource formDs = this;
    RetailPeriodicDiscount retailPeriodicDiscount = formDs.cursor();

    next initValue();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        RetailDiscountOfferTypeBase periodicDiscountType = retailPeriodicDiscount.PeriodicDiscountType;

        if (periodicDiscountType == RetailDiscountOfferTypeBase::Promotion)
        {
            retailPeriodicDiscount.ConcurrencyMode = RetailDiscountConcurrency::Compounded;
            retailPeriodicDiscount.PriceComponentType = GUPPriceComponent::PriceMarginComponentAdjustment;
        }
        else if (periodicDiscountType == RetailDiscountOfferTypeBase::DiscountOffer ||
                 periodicDiscountType == RetailDiscountOfferTypeBase::Multibuy      ||
                 periodicDiscountType == RetailDiscountOfferTypeBase::MixAndMatch   ||
                 periodicDiscountType == RetailDiscountOfferTypeBase::Threshold     )
        {
            retailPeriodicDiscount.PriceComponentType = GUPPriceComponent::RetailDiscounts;
        }

        retailPeriodicDiscount.HeaderPricingGroupCode = GUPGroupAll::All;
        retailPeriodicDiscount.IsGupDiscount = NoYes::Yes;
    }
}

public void init()
{
    next init();

    FormDataSource formDs = this;
    QueryBuildDataSource qbds = formDs.queryBuildDataSource();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        qbds.addRange(fieldNum(RetailPeriodicDiscount, IsGupDiscount)).value(any2Str(NoYes::Yes));
    }
    else
    {
        qbds.addRange(fieldNum(RetailPeriodicDiscount, IsGupDiscount)).value(any2Str(NoYes::No));
    }
}
